1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	
6	const BASE_PREMIUMS: Record<string, number> = {
7	  sword: 100,
8	  amulet: 60,
9	  staff: 80,
10	  potion: 40,
11	  rune: 25,
12	  moonstone: 25,
13	};
14	
15	const PERCENT_WHOLE = 100;
16	
17	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
18	// floating-point error that shifts the spec's round-up in MHPCO's favour.
19	const percentOf = (percent: number, amount: number): number =>
20	  (amount * percent) / PERCENT_WHOLE;
21	
22	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
23	// round up, payouts (MHPCO pays) round down.
24	const roundPremiumInMHPCOsFavour = Math.ceil;
25	
26	export type ScenarioResult = { premium: number };
27	
28	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
29	// the surcharge and claim tests still to come). They are typed as optional so
30	// the scenarios the tests actually send typecheck, without pricing them.
31	type Item = {
32	  type: string;
33	  material?: string;
34	  enchantment?: number;
35	  cursed?: boolean;
36	};
37	
38	type Step = { op: string; items: Item[] };
39	
40	// `customer` and `op` are likewise unread so far: the loyalty-discount and
41	// follow-up-contract tests will reach for them.
42	type Scenario = {
43	  customer: { yearsWithMHPCO: number };
44	  steps: Step[];
45	};
46	
47	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
48	
49	const sumBasePremiums = (items: Item[]): number =>
50	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
51	
52	const groupByType = (items: Item[]): Item[][] => {
53	  const groups = new Map<string, Item[]>();
54	  for (const item of items) {
55	    const group = groups.get(item.type) ?? [];
56	    group.push(item);
57	    groups.set(item.type, group);
58	  }
59	  return [...groups.values()];
60	};
61	
62	// A block is a discount on the components' combined base premium, not a flat
63	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
64	// 20 % stays visible as the rule it is.
65	const blockBasePremium = (items: Item[]): number => {
66	  const undiscounted = sumBasePremiums(items);
67	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
68	};
69	
70	// The block applies per group of alike items, and only at exactly BLOCK_SIZE:
71	// 4 or 7 runes form no block, but 3 runes and 3 moonstones form one each.
72	const policyBasePremiumFor = (items: Item[]): number =>
73	  groupByType(items)
74	    .map((group) => (group.length === BLOCK_SIZE ? blockBasePremium(group) : sumBasePremiums(group)))
75	    .reduce((total, groupPremium) => total + groupPremium, 0);
76	
77	const quoteFor = (items: Item[]): ScenarioResult => {
78	  const policyBasePremium = policyBasePremiumFor(items);
79	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
80	  const premium = roundPremiumInMHPCOsFavour(
81	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
82	  );
83	  return { premium };
84	};
85	
86	// Every scenario so far holds exactly one quote step, so only the first is
87	// priced. The follow-up-contract discount test will drive priced-per-step.
88	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
89	  const [firstStep] = scenario.steps;
90	  return { results: [quoteFor(firstStep.items)] };
91	};
