// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
// pile is never cheaper than the block it contains.
const formsABlock = (alikeItems: Item[]): boolean => alikeItems.length === BLOCK_SIZE;

const basePremiumForGroup = (alikeItems: Item[]): number =>
  formsABlock(alikeItems) ? blockBasePremium(alikeItems) : sumBasePremiums(alikeItems);

// Priced per group of alike items rather than over the whole list, so 3 runes
// and 3 moonstones each form their own block.
const policyBasePremiumFor = (items: Item[]): number =>
  groupByType(items)
    .map(basePremiumForGroup)
    .reduce((total, groupPremium) => total + groupPremium, 0);
